INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ALAWITE','Alawite / Nusayri tradition',850,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_FRIEDMAN_NUSAYRI','secondary scholarship','Yaron Friedman, The Nusayri-Alawis: An Introduction to the Religion, History and Identity of the Leading Minority in Syria (Islamic History and Civilization 77; Leiden: Brill, 2010)','Foundational scholarly survey of Nusayri-Alawi doctrine (Ayn-Mim-Sin trinity, cyclical manifestation), history, and the lineage from Ibn Nusayr through al-Khasibi.'),
 ('SRC_HALM_GNOSIS','secondary scholarship','Heinz Halm, Die islamische Gnosis: Die extreme Schia und die ''Alawiten (Zurich/Munich: Artemis, 1982)','Standard study of the ghulat (extreme Shi''a) and Alawite gnostic cosmology, divine manifestation cycles, and the Ma''na-Ism-Bab triad.'),
 ('SRC_BAR_ASHER_KOFSKY','secondary scholarship','Meir M. Bar-Asher and Aryeh Kofsky, The Nusayri-''Alawi Religion: An Enquiry into its Theology and Liturgy (Jerusalem Studies in Religion and Culture 1; Leiden: Brill, 2002)','Detailed analysis of Nusayri theology and liturgy, including the deification of Ali, the role of Muhammad and Salman, and the seven cycles of manifestation (adwar).')
INSERT INTO _e VALUES
 ('ENT_ALW_TRINITY','Ayn-Mim-Sin (the Alawite Trinity)','Divine collective','Divine collective','Alawite','divine triad,manifestation,cosmology','B','Attested (Friedman 2010; Bar-Asher & Kofsky 2002) as the central Nusayri-Alawi triad of three letters: Ayn (Ali), Mim (Muhammad), Sin (Salman). Cohort hub.'),
 ('ENT_ALW_ALI','Ali (the Ma''na / Meaning)','Deified figure','Deified figure','Alawite','divine essence,meaning,supreme principle','B','Attested: in Nusayri-Alawi doctrine Ali ibn Abi Talib is the Ma''na, the divine essence/Meaning behind manifestation. Homonym/same person as mainstream Shi''i Imam ENT_ISL_ALI, venerated differently (deified, not merely first Imam).'),
 ('ENT_ALW_MUHAMMAD','Muhammad (the Ism / Name)','Divine manifestation','Divine manifestation','Alawite','name,veil,manifestation','B','Attested: Muhammad is the Ism (Name) and the hijab/veil through which the Ma''na is manifested. Same person as the Prophet ENT_ISL_MUHAMMAD, theologically subordinated to Ali in Nusayri doctrine (homonym).'),
 ('ENT_ALW_SALMAN','Salman (the Bab / Gate)','Divine manifestation','Divine manifestation','Alawite','gate,mediation,initiation','B','Attested: Salman al-Farisi is the Bab (Gate), the mediating gateway who transmits knowledge of the Ma''na. Same person as ENT_ISL_SALMAN, Companion of the Prophet (homonym).'),
 ('ENT_ALW_MANA','al-Ma''na (the Meaning)','Divine principle/person','Divine principle','Alawite','divine essence,meaning,supreme principle','B','Attested doctrinal principle (Halm 1982; Bar-Asher & Kofsky 2002): the hidden divine essence/Meaning, the first hypostasis of the triad, embodied in each cycle by Ali.'),
 ('ENT_ALW_ISM','al-Ism (the Name)','Divine principle/person','Divine principle','Alawite','name,veil,manifestation','B','Attested doctrinal principle: the Name, the second hypostasis emanated from the Ma''na, the veil of manifestation, borne by Muhammad in the Muhammadan cycle.'),
 ('ENT_ALW_BAB','al-Bab (the Gate)','Divine principle/person','Divine principle','Alawite','gate,mediation,initiation','B','Attested doctrinal principle: the Gate, third hypostasis emanated from the Name, the mediator of esoteric knowledge, borne by Salman in the Muhammadan cycle.'),
 ('ENT_ALW_IBN_NUSAYR','Ibn Nusayr al-Namiri','Prophet/revealer','Prophet/revealer','Alawite','founder,prophecy,revelation','B','Attested historical figure (d. c. 868): Abu Shu''ayb Muhammad ibn Nusayr al-Namiri al-Numayri, the eponymous founder-prophet of the Nusayriyya, who claimed to be the Bab of the tenth Imam Ali al-Hadi / al-Askari (Friedman 2010).'),
 ('ENT_ALW_KHASIBI','al-Husayn ibn Hamdan al-Khasibi','Sufi master/author','Theologian','Alawite','doctrine,organization,theology','B','Attested historical figure (d. c. 969): the organizer and systematizer of the Nusayri religion, author of the Kitab al-Hidaya al-Kubra, who established the community in Aleppo and Baghdad (Friedman 2010; Bar-Asher & Kofsky 2002).'),
 ('ENT_ALW_AYN_MIM_SIN_DOCTRINE','Ayn-Mim-Sin (the trinitarian formula)','Doctrine','Doctrine','Alawite','theology,trinity,initiation','B','Attested core doctrine: the AMS confession encoding the triad Ma''na-Ism-Bab (Ali-Muhammad-Salman), recited as the foundational creed of the initiated (Bar-Asher & Kofsky 2002).'),
 ('ENT_ALW_SEVEN_CYCLES','The Seven Cycles of Manifestation (al-Adwar al-Sab''a)','Doctrine','Doctrine','Alawite','cyclical manifestation,cosmology,history','B','Attested doctrine (Halm 1982; Bar-Asher & Kofsky 2002): the Ma''na manifests through seven historical cycles, each with its own Ism and Bab, culminating in the Ali-Muhammad-Salman (Muhammadan) cycle.'),
 ('ENT_ALW_TAQAMMUS','Tanasukh / Taqammus (transmigration of souls)','Doctrine','Doctrine','Alawite','soul,reincarnation,eschatology','B','Attested doctrine: belief in the transmigration/metempsychosis of souls (taqammus), tied to the cyclical descent of the divine and the moral state of the initiate (Friedman 2010).'),
 ('ENT_ALW_MUQADDASIYYA','The Aytam / Five Incomparable Ones (al-Aytam al-Khamsa)','Holy collective','Holy collective','Alawite','cosmology,intercession,sacred company','C','Attested cosmological collective (Bar-Asher & Kofsky 2002): the five ''orphans/incomparables'' (aytam), spiritual hierarchs emanated below the Bab who administer the cosmos. Publicly attested function only.');
