INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_ALW_TRINITY','PER_ALAWITE','Attested (Friedman 2010; Bar-Asher & Kofsky 2002) as the central Nusayri-Alawi triad of three letters: Ayn (Ali), Mim (Muhammad), Sin (Salman). Cohort hub.'),
 ('ENT_ALW_ALI','PER_ALAWITE','Attested: in Nusayri-Alawi doctrine Ali ibn Abi Talib is the Ma''na, the divine essence/Meaning behind manifestation. Homonym/same person as mainstream Shi''i Imam ENT_ISL_ALI, venerated differently (deified, not merely first Imam).'),
 ('ENT_ALW_MUHAMMAD','PER_ALAWITE','Attested: Muhammad is the Ism (Name) and the hijab/veil through which the Ma''na is manifested. Same person as the Prophet ENT_ISL_MUHAMMAD, theologically subordinated to Ali in Nusayri doctrine (homonym).'),
 ('ENT_ALW_SALMAN','PER_ALAWITE','Attested: Salman al-Farisi is the Bab (Gate), the mediating gateway who transmits knowledge of the Ma''na. Same person as ENT_ISL_SALMAN, Companion of the Prophet (homonym).'),
 ('ENT_ALW_MANA','PER_ALAWITE','Attested doctrinal principle (Halm 1982; Bar-Asher & Kofsky 2002): the hidden divine essence/Meaning, the first hypostasis of the triad, embodied in each cycle by Ali.'),
 ('ENT_ALW_ISM','PER_ALAWITE','Attested doctrinal principle: the Name, the second hypostasis emanated from the Ma''na, the veil of manifestation, borne by Muhammad in the Muhammadan cycle.'),
 ('ENT_ALW_BAB','PER_ALAWITE','Attested doctrinal principle: the Gate, third hypostasis emanated from the Name, the mediator of esoteric knowledge, borne by Salman in the Muhammadan cycle.'),
 ('ENT_ALW_IBN_NUSAYR','PER_ALAWITE','Attested historical figure (d. c. 868): Abu Shu''ayb Muhammad ibn Nusayr al-Namiri al-Numayri, the eponymous founder-prophet of the Nusayriyya, who claimed to be the Bab of the tenth Imam Ali al-Hadi / al-Askari (Friedman 2010).'),
 ('ENT_ALW_KHASIBI','PER_ALAWITE','Attested historical figure (d. c. 969): the organizer and systematizer of the Nusayri religion, author of the Kitab al-Hidaya al-Kubra, who established the community in Aleppo and Baghdad (Friedman 2010; Bar-Asher & Kofsky 2002).'),
 ('ENT_ALW_AYN_MIM_SIN_DOCTRINE','PER_ALAWITE','Attested core doctrine: the AMS confession encoding the triad Ma''na-Ism-Bab (Ali-Muhammad-Salman), recited as the foundational creed of the initiated (Bar-Asher & Kofsky 2002).'),
 ('ENT_ALW_SEVEN_CYCLES','PER_ALAWITE','Attested doctrine (Halm 1982; Bar-Asher & Kofsky 2002): the Ma''na manifests through seven historical cycles, each with its own Ism and Bab, culminating in the Ali-Muhammad-Salman (Muhammadan) cycle.'),
 ('ENT_ALW_TAQAMMUS','PER_ALAWITE','Attested doctrine: belief in the transmigration/metempsychosis of souls (taqammus), tied to the cyclical descent of the divine and the moral state of the initiate (Friedman 2010).'),
 ('ENT_ALW_MUQADDASIYYA','PER_ALAWITE','Attested cosmological collective (Bar-Asher & Kofsky 2002): the five ''orphans/incomparables'' (aytam), spiritual hierarchs emanated below the Bab who administer the cosmos. Publicly attested function only.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_ALW_ALI','member_of','ENT_ALW_TRINITY','high','Ali as the Ma''na (Ayn) is the first member of the Ayn-Mim-Sin triad (Friedman 2010; Bar-Asher & Kofsky 2002).'),
 ('ENT_ALW_MUHAMMAD','member_of','ENT_ALW_TRINITY','high','Muhammad as the Ism (Mim) is the second member of the Ayn-Mim-Sin triad.'),
 ('ENT_ALW_SALMAN','member_of','ENT_ALW_TRINITY','high','Salman as the Bab (Sin) is the third member of the Ayn-Mim-Sin triad.'),
 ('ENT_ALW_ALI','embodies','ENT_ALW_MANA','high','In Nusayri doctrine Ali is the manifestation/embodiment of the divine Ma''na (Meaning), the supreme essence (Halm 1982).'),
 ('ENT_ALW_MUHAMMAD','embodies','ENT_ALW_ISM','high','Muhammad embodies al-Ism, the Name/veil, in the Muhammadan cycle (Halm 1982).'),
 ('ENT_ALW_SALMAN','embodies','ENT_ALW_BAB','high','Salman embodies al-Bab, the Gate, in the Muhammadan cycle (Halm 1982).'),
 ('ENT_ALW_ISM','emanates_from','ENT_ALW_MANA','high','Nusayri emanationist cosmology: the Name (Ism) is emanated from the Meaning (Ma''na) (Bar-Asher & Kofsky 2002).'),
 ('ENT_ALW_BAB','emanates_from','ENT_ALW_ISM','high','The Gate (Bab) is emanated from the Name (Ism), completing the descending triad (Bar-Asher & Kofsky 2002).'),
 ('ENT_ALW_MUQADDASIYYA','emanates_from','ENT_ALW_BAB','medium','The five Aytam are attested as emanated below the Bab in the Nusayri cosmic hierarchy (Bar-Asher & Kofsky 2002).'),
 ('ENT_ALW_AYN_MIM_SIN_DOCTRINE','symbolizes','ENT_ALW_TRINITY','high','The Ayn-Mim-Sin formula is the creedal expression that names and symbolizes the divine triad (Bar-Asher & Kofsky 2002).'),
 ('ENT_ALW_TRINITY','member_of','ENT_ALW_SEVEN_CYCLES','medium','The Ali-Muhammad-Salman triad constitutes the final (Muhammadan) cycle within the doctrine of seven cycles of manifestation (Halm 1982).'),
 ('ENT_ALW_IBN_NUSAYR','reveals','ENT_ALW_AYN_MIM_SIN_DOCTRINE','medium','Ibn Nusayr al-Namiri is the founder-prophet credited with proclaiming the deification of Ali and the trinitarian doctrine (Friedman 2010).'),
 ('ENT_ALW_IBN_NUSAYR','embodies','ENT_ALW_BAB','medium','Ibn Nusayr claimed to be the Bab (Gate) of the Imams Ali al-Hadi and Hasan al-Askari, occupying/embodying the Bab office in his own age (Friedman 2010). [QA: verb changed from member_of to embodies — an entity cannot be member_of a divine principle.]'),
 ('ENT_ALW_KHASIBI','taught_by','ENT_ALW_IBN_NUSAYR','medium','Al-Khasibi stands in the doctrinal lineage descending from Ibn Nusayr, whose teaching he systematized and organized (Friedman 2010).'),
 ('ENT_ALW_KHASIBI','transmits','ENT_ALW_SEVEN_CYCLES','medium','Al-Khasibi systematized and transmitted Nusayri cosmology including the cyclical-manifestation doctrine in his Kitab al-Hidaya al-Kubra (Bar-Asher & Kofsky 2002).'),
 ('ENT_ALW_ALI','reception_of','ENT_ISL_ALI','high','The Alawite deified Ali (Ma''na) is a sectarian reception of the same historical Ali ibn Abi Talib venerated in mainstream/Twelver Shi''ism as first Imam (homonym, same person, divergent theology; Friedman 2010).'),
 ('ENT_ALW_MUHAMMAD','reception_of','ENT_ISL_MUHAMMAD','high','The Alawite Muhammad (Ism/veil) is a sectarian reception of the Prophet Muhammad, here theologically subordinated to Ali (homonym, same person; Friedman 2010).'),
 ('ENT_ALW_SALMAN','reception_of','ENT_ISL_SALMAN','high','The Alawite Salman (Bab/Gate) is a sectarian reception of the Companion Salman al-Farisi, elevated to the third hypostasis of the triad (homonym, same person; Friedman 2010).'),
 ('ENT_ALW_IBN_NUSAYR','aligned_with','ENT_ISL_ASKARI','medium','Ibn Nusayr is historically associated as a disciple/claimed Bab of the eleventh Imam Hasan al-Askari, linking the sect''s origin to the Twelver Imami line (Friedman 2010).'),
 ('ENT_ALW_SEVEN_CYCLES','reception_of','ENT_ISL_IMAMAH','low','The Alawite cyclical-manifestation doctrine develops out of and radicalizes the Shi''i doctrine of Imamah / divinely-guided guidance (Halm 1982).');
